package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 计划内一条区段占用，区间左闭右开 [startUtc, endUtc)。
 *
 * @param id                   主键
 * @param planId               所属计划 id
 * @param seq                  计划内序号，保持提交顺序
 * @param trainNo              列车编号
 * @param sectionId            区段 ID
 * @param startUtc             占用开始时刻（含），UTC
 * @param endUtc               占用结束时刻（不含），UTC，必须晚于 startUtc
 * @param direction            行车方向标识，须为区段单线配置的正/反方向之一；区段无配置时为 null
 * @param appliedConfigVersion 发布成功时冻结的区段配置版本；草稿或无配置区段为 null，取消不改写
 */
public record Occupancy(long id, long planId, int seq, String trainNo, String sectionId,
                        Instant startUtc, Instant endUtc, String direction,
                        Integer appliedConfigVersion) {
}

package com.example.starter.plan.model;

/**
 * 单线区段换向配置：相邻反向占用须满足清空间隔，同向仅遵守互斥。
 *
 * @param id                主键
 * @param sectionId         区段 ID，全局唯一
 * @param directionForward  正向行车方向标识
 * @param directionBackward 反向行车方向标识
 * @param clearanceSeconds  换向清空间隔（整秒，1 至 600）
 * @param version           配置版本，从 1 起，每次更新加一
 */
public record SectionConfig(long id, String sectionId, String directionForward,
                            String directionBackward, int clearanceSeconds, int version) {

    /**
     * 判断给定方向是否为配置允许的正/反方向之一。
     */
    public boolean allows(String direction) {
        return directionForward.equals(direction) || directionBackward.equals(direction);
    }
}

package com.example.starter.plan.model;

import java.time.Instant;

/**
 * 已发布计划的一条生效时隙（跨计划冲突检测与查询结果共用）。
 *
 * @param scheduleKey 所属计划业务键
 * @param trainNo     列车编号
 * @param sectionId   区段 ID
 * @param startUtc    占用开始（含），UTC
 * @param endUtc      占用结束（不含），UTC
 * @param direction   行车方向标识；区段无配置时为 null
 */
public record PublishedSlot(String scheduleKey, String trainNo, String sectionId,
                            Instant startUtc, Instant endUtc, String direction) {
}

package com.example.starter.plan.model;

import java.time.Instant;
import java.time.LocalDate;

/**
 * 指定区段上一条已发布占用（含运营日），用于单线配置变更时按运营日分组验证已发布集合。
 *
 * @param scheduleKey 所属计划业务键
 * @param trainNo     列车编号
 * @param opDate      运营日期（Asia/Shanghai 日历日）
 * @param startUtc    占用开始（含），UTC
 * @param endUtc      占用结束（不含），UTC
 * @param direction   行车方向标识；为 null 表示旧无方向占用，须先取消，不能猜方向
 */
public record SectionSlot(String scheduleKey, String trainNo, LocalDate opDate,
                          Instant startUtc, Instant endUtc, String direction) {
}

